  "application": "data-visualization",
  "case_id": "case-social-digital-divide-internet-penetration-inequality",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "stark, data-dense, publication-ready"
  },
  "goal": [
    {
      "id": "four-dimension-inequality",
      "insight": "Present a unified visual narrative showing internet penetration gaps across all four dimensions (income, age, urban-rural, region) so the viewer can compare the magnitude of each divide at a glance"
    },
    {
      "id": "income-gradient-gap",
      "insight": "Highlight the steep gradient in internet penetration from the lowest to highest income quintile, making the spread between Q1 and Q5 visually prominent"
    },
    {
      "id": "regional-disparity",
      "insight": "Emphasize the contrast in penetration rates between Sub-Saharan Africa / South Asia and Europe / North America across all sub-dimensions"
    },
    {
      "id": "urban-rural-split",
      "insight": "Show the urban-rural gap within each region, drawing attention to where this gap is largest versus where it is narrowest"
    },
    {
      "id": "youth-elder-contrast",
      "insight": "Compare internet penetration between the youngest (15-24) and oldest (65+) age groups across regions, making the age divide visually clear"
    }
  ]
}

